+import type { AnyColumn } from '~/column.ts';
+import { is } from '~/entity.ts';
+import { Column } from '~/column.ts';
+import { type SQL, sql, type SQLWrapper } from '../sql.ts';
+
+export type WindowBoundary =
+	| { readonly kind: 'unbounded preceding' }
+	| { readonly kind: 'current row' }
+	| { readonly kind: 'unbounded following' }
+	| { readonly kind: 'preceding'; readonly value: number }
+	| { readonly kind: 'following'; readonly value: number };
+
+export const unboundedPreceding: WindowBoundary = { kind: 'unbounded preceding' };
+export const currentRow: WindowBoundary = { kind: 'current row' };
+export const unboundedFollowing: WindowBoundary = { kind: 'unbounded following' };
+
+function position(boundary: WindowBoundary): number {
+	if (boundary.kind === 'unbounded preceding') return Number.NEGATIVE_INFINITY;
+	if (boundary.kind === 'unbounded following') return Number.POSITIVE_INFINITY;
+	if (boundary.kind === 'preceding') return -boundary.value;
+	if (boundary.kind === 'following') return boundary.value;
+	return 0;
+}
+
+function validateOffset(name: string, value: number): void {
+	if (!Number.isInteger(value) || value < 0) {
+		throw new Error(`${name}() requires a non-negative integer; received ${value}`);
+	}
+}
+
+export function preceding(value: number): WindowBoundary {
+	validateOffset('preceding', value);
+	return { kind: 'preceding', value };
+}
+
+export function following(value: number): WindowBoundary {
+	validateOffset('following', value);
+	return { kind: 'following', value };
+}
+
+export interface WindowFrame {
+	readonly type: 'rows' | 'range';
+	readonly from: WindowBoundary;
+	readonly to: WindowBoundary;
+}
+
+function frame(type: WindowFrame['type'], spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	if (position(spec.from) > position(spec.to)) {
+		throw new Error('Window frame "from" boundary must not be ordered after "to" boundary');
+	}
+	return { type, ...spec };
+}
+
+export function rows(spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: WindowBoundary; to: WindowBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | SQLWrapper[];
+	orderBy?: SQLWrapper | SQLWrapper[];
+	frame?: WindowFrame;
+}
+
+export interface WindowDefinition {
+	name: string;
+	spec: WindowSpec;
+}
+
+function boundarySql(boundary: WindowBoundary): SQL {
+	switch (boundary.kind) {
+		case 'preceding': return sql.raw(`${boundary.value} preceding`);
+		case 'following': return sql.raw(`${boundary.value} following`);
+		default: return sql.raw(boundary.kind);
+	}
+}
+
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const chunks: SQL[] = [];
+	const partitionBy = spec.partitionBy === undefined ? [] : Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy];
+	const orderBy = spec.orderBy === undefined ? [] : Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy];
+	if (partitionBy.length) chunks.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
+	if (orderBy.length) chunks.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
+	if (spec.frame) chunks.push(sql`${sql.raw(spec.frame.type)} between ${boundarySql(spec.frame.from)} and ${boundarySql(spec.frame.to)}`);
+	return sql.join(chunks, sql` `);
+}
+
+export class WindowFunction<T> implements SQLWrapper {
+	constructor(private readonly expression: SQL<T>) {}
+
+	over(spec?: WindowSpec | string): SQL<T> {
+		if (typeof spec === 'string') return sql`${this.expression} over ${sql.identifier(spec)}`;
+		return sql`${this.expression} over (${buildWindowSpec(spec ?? {})})`;
+	}
+
+	getSQL(): SQL<T> {
+		return this.expression;
+	}
+}
+
+function positional(name: string, value: number): SQL {
+	if (!Number.isInteger(value) || value <= 0) {
+		throw new Error(`${name}() requires a positive integer; received ${value}`);
+	}
+	return sql.raw(String(value));
+}
+
+function valueType<T extends SQLWrapper>(expression: T): SQL<(T extends AnyColumn ? T['_']['data'] : string) | null> {
+	return sql`${expression}`.mapWith(is(expression, Column) ? expression : String) as any;
+}
+
+export function rowNumber(): WindowFunction<number> { return new WindowFunction(sql`row_number()`.mapWith(Number)); }
+export function rank(): WindowFunction<number> { return new WindowFunction(sql`rank()`.mapWith(Number)); }
+export function denseRank(): WindowFunction<number> { return new WindowFunction(sql`dense_rank()`.mapWith(Number)); }
+export function ntile(buckets: number): WindowFunction<number> { return new WindowFunction(sql`ntile(${positional('ntile', buckets)})`.mapWith(Number)); }
+export function percentRank(): WindowFunction<number> { return new WindowFunction(sql`percent_rank()`.mapWith(Number)); }
+export function cumeDist(): WindowFunction<number> { return new WindowFunction(sql`cume_dist()`.mapWith(Number)); }
+
+export function lag<T extends SQLWrapper>(expression: T): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null>;
+export function lag<T extends SQLWrapper, TDefault>(expression: T, offset: number | undefined, defaultValue: TDefault): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | TDefault>;
+export function lag(expression: SQLWrapper, offset?: number, defaultValue?: unknown): WindowFunction<any> {
+	const args = [expression, ...(offset === undefined ? [] : [sql.raw(String(offset)])), ...(defaultValue === undefined ? [] : [defaultValue as any])];
+	return new WindowFunction(sql`lag(${sql.join(args, sql`, `)})`);
+}
+export function lead<T extends SQLWrapper>(expression: T): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | null>;
+export function lead<T extends SQLWrapper, TDefault>(expression: T, offset: number | undefined, defaultValue: TDefault): WindowFunction<(T extends AnyColumn ? T['_']['data'] : string) | TDefault>;
